contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, bytes calldata data) public payable {
        require(amount > 0, "amount must be positive");
        require(address(this).balance >= amount, "insufficient balance");

        uint countBefore = c.depositsCount();
        uint balanceBefore = address(c).balance;

        bool reverted;
        try c.call{value: amount}(data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint countAfter = c.depositsCount();
        uint balanceAfter = address(c).balance;

        assert(reverted
            ? (countAfter == countBefore && balanceAfter == balanceBefore)
            : (countAfter == countBefore + 1 && balanceAfter == balanceBefore + amount));
    }

    receive() external payable {}
}

