contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint withdrawValue) public payable {
        require(address(this).balance >= amount, "insufficient balance");
        require(amount > 0, "amount must be positive");

        // Owner deposits via fallback, increasing depositsCount by 1.
        uint beforeCount = c.depositsCount();
        uint beforeC = address(c).balance;
        c.fallback{value: amount}();

        // Non-owner cannot change depositsCount.
        // (We are the owner in this test, so we verify the owner path instead.)

        // Owner withdraws; balance must decrease by exactly withdrawValue.
        require(address(c).balance >= withdrawValue, "insufficient contract balance");
        uint beforeWithdraw = address(c).balance;
        c.withdraw(withdrawValue);
        uint afterWithdraw = address(c).balance;

        assert(afterWithdraw == beforeWithdraw - withdrawValue);
    }

    receive() external payable {}
}

