contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address target, uint value, bytes memory data, uint depositValue) public payable {
        require(address(this).balance >= value + depositValue, "insufficient balance");

        uint beforeCount = c.depositsCount();
        uint beforeBalance = address(c).balance;
        uint beforeTargetBalance = target.balance;

        bool reverted;
        try c.sendMoney{value: value}(target, value, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterCount = c.depositsCount();
        uint afterBalance = address(c).balance;
        uint afterTargetBalance = target.balance;

        // If sendMoney succeeded, the target must have received exactly value and count must not decrease.
        // If it reverted, no state change should persist (balance and count unchanged).
        assert(
            (reverted && afterCount == beforeCount && afterBalance == beforeBalance && afterTargetBalance == beforeTargetBalance) ||
            (!reverted && afterCount >= beforeCount && afterTargetBalance == beforeTargetBalance + value && afterBalance == beforeBalance - value)
        );
    }

    receive() external payable {}
}

