    function run(address target, uint value, bytes memory data) public payable {
        require(address(this).balance >= value, "insufficient balance");
        require(target != address(c), "target must not be C itself");

        uint beforeBalance = address(c).balance;
        uint beforeTargetBalance = target.balance;

        bool reverted;
        c.sendMoney(target, value, data);
        reverted = false;

        uint afterBalance = address(c).balance;
        uint afterTargetBalance = target.balance;

        // General rule: a successful sendMoney cannot increase C's balance and can move at most `value`
        // to the target; if it reverts, no balance changes should persist.
        assert(
            reverted
                ? (afterBalance == beforeBalance && afterTargetBalance == beforeTargetBalance)
